package server
import "net/http"
const indexHTML=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BotWeb</title><link rel="stylesheet" href="/app.css"></head><body><header><div><strong>BotWeb</strong><span>PBMP fleet console</span></div><button id="refresh" type="button">Refresh</button></header><main><section class="summary"><div><b id="total">0</b><span>registered</span></div><div><b id="online">0</b><span>online</span></div><div><b id="offline">0</b><span>offline</span></div></section><p id="notice" role="status">Loading fleet…</p><section id="fleet" class="fleet" aria-live="polite"></section></main><script src="/app.js"></script></body></html>`
const css=`:root{font-family:system-ui,sans-serif;color-scheme:dark;background:#101318;color:#edf1f7}*{box-sizing:border-box}body{margin:0}header{display:flex;justify-content:space-between;align-items:center;padding:1.1rem 5vw;border-bottom:1px solid #2a3039}header strong{font-size:1.4rem}header span{margin-left:.8rem;color:#9da8b7}button{padding:.55rem .9rem;border:1px solid #4b5666;border-radius:.45rem;background:#202630;color:inherit}main{max-width:1100px;margin:auto;padding:2rem 5vw}.summary{display:flex;gap:1rem;margin-bottom:1.5rem}.summary div,.card{background:#171c23;border:1px solid #2b333e;border-radius:.65rem}.summary div{padding:1rem 1.4rem;min-width:8rem}.summary b{display:block;font-size:1.6rem}.summary span,.muted{color:#9da8b7}.fleet{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1rem}.card{padding:1.1rem}.top{display:flex;justify-content:space-between;gap:1rem}.state{font-size:.8rem;text-transform:uppercase;letter-spacing:.05em}.online{color:#86d993}.offline{color:#e59a9a}.caps{display:flex;flex-wrap:wrap;gap:.35rem}.cap{font-size:.75rem;border:1px solid #394351;border-radius:1rem;padding:.2rem .5rem}.network{display:flex;justify-content:space-between;padding:.35rem 0;border-top:1px solid #252c35}h2{margin:.1rem 0}.error{color:#e59a9a}@media(max-width:600px){header span{display:none}.summary{overflow:auto}}`
const js=`const q=s=>document.querySelector(s),fleet=q('#fleet'),notice=q('#notice');async function get(u){const r=await fetch(u,{headers:{Accept:'application/json'}});if(!r.ok)throw new Error('HTTP '+r.status);return r.json()}function esc(s){const d=document.createElement('div');d.textContent=String(s??'');return d.innerHTML}async function card(b){let info,caps,nets;try{[info,caps,nets]=await Promise.all([get('/api/v1/bots/'+encodeURIComponent(b.id)+'/info'),get('/api/v1/bots/'+encodeURIComponent(b.id)+'/capabilities'),get('/api/v1/bots/'+encodeURIComponent(b.id)+'/networks')])}catch(e){return {online:false,html:'<article class="card"><div class="top"><h2>'+esc(b.name)+'</h2><span class="state offline">unreachable</span></div><p class="error">PBMP unavailable</p><p class="muted">'+esc(b.id)+'</p></article>'}}const on=info.state==='online';const ns=(nets.networks||[]).map(n=>'<div class="network"><span>'+esc(n.name)+'</span><span class="muted">'+esc(n.state)+'</span></div>').join('');const cs=(caps.capabilities||[]).map(c=>'<span class="cap">'+esc(c)+'</span>').join('');return {online:on,html:'<article class="card"><div class="top"><div><h2>'+esc(b.name)+'</h2><span class="muted">'+esc(info.implementation)+' '+esc(info.version)+'</span></div><span class="state '+(on?'online':'offline')+'">'+esc(info.state)+'</span></div><p class="muted">'+esc(b.id)+'</p><h3>Networks</h3>'+(ns||'<p class="muted">None reported</p>')+'<h3>Capabilities</h3><div class="caps">'+cs+'</div></article>'}}async function load(){notice.textContent='Loading fleet…';fleet.innerHTML='';try{const bots=await get('/api/v1/bots');const cards=await Promise.all(bots.map(card));fleet.innerHTML=cards.map(x=>x.html).join('');q('#total').textContent=bots.length;q('#online').textContent=cards.filter(x=>x.online).length;q('#offline').textContent=cards.filter(x=>!x.online).length;notice.textContent=bots.length?'Fleet refreshed.':'No bots registered.'}catch(e){notice.textContent='Unable to load registry.';notice.className='error'}}q('#refresh').addEventListener('click',load);load();`
func assetCSS(w http.ResponseWriter,_ *http.Request){w.Header().Set("Content-Type","text/css; charset=utf-8");w.Write([]byte(css))}
func assetJS(w http.ResponseWriter,_ *http.Request){w.Header().Set("Content-Type","application/javascript; charset=utf-8");w.Write([]byte(js))}
